<?php
require_once '../config/db.php'; require_once '../includes/auth.php'; require_login();
$allowed = get_user_allowed_categories(); if (!$allowed) die('Access Denied.');
$placeholders = implode(',', array_fill(0, count($allowed), '?')); $search = trim($_GET['search'] ?? '');
$sql = "SELECT p.*, a.allottee_name FROM properties p LEFT JOIN allottees a ON a.property_id=p.id WHERE p.category IN ($placeholders) AND a.id IS NULL"; $params = $allowed;
if ($search !== '') { $sql .= ' AND (p.property_no LIKE ? OR p.property_code LIKE ? OR p.scheme_name LIKE ?)'; $like = "%$search%"; array_push($params, $like, $like, $like); }
$sql .= ' ORDER BY p.created_at DESC'; $stmt = $pdo->prepare($sql); $stmt->execute($params); $properties = $stmt->fetchAll();
?><!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Vacant Property Search</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="../assets/css/style.css" rel="stylesheet"></head><body><div class="portal-wrapper"><header class="portal-header"><div class="portal-brand">🔎 Vacant Property Search</div><div class="portal-header-actions"><a href="admin.php" class="btn btn-sm btn-outline-light">Dashboard</a><a href="../logout.php" class="btn btn-sm btn-light">Logout</a></div></header><main class="portal-main"><div class="portal-page-header"><h1 class="portal-page-title">Property Search</h1><p class="portal-page-subtitle">Sirf vacant properties yahan show hongi.</p></div><div class="dashboard-shell mb-3"><form class="row g-2"><div class="col-md-10"><input name="search" class="form-control" value="<?= htmlspecialchars($search) ?>" placeholder="Search property no, ID or scheme"></div><div class="col-md-2"><button class="btn btn-primary w-100">Search</button></div></form></div><div class="dashboard-shell table-responsive"><table class="table align-middle mb-0"><thead><tr><th>S.No.</th><th>Property ID</th><th>Scheme</th><th>Type</th><th>Size</th><th>Price</th><th>Action</th></tr></thead><tbody><?php foreach ($properties as $i => $p): ?><tr><td><?= $i + 1 ?></td><td><?= htmlspecialchars($p['property_code']) ?><br><small><?= htmlspecialchars($p['property_no']) ?></small></td><td><?= htmlspecialchars($p['scheme_name']) ?></td><td><?= htmlspecialchars($p['property_type'] ?? 'Residential') ?><br><small><?= htmlspecialchars($p['category']) ?></small></td><td><?= htmlspecialchars($p['area_size']) ?></td><td>₹<?= number_format($p['price'], 2) ?></td><td><a href="property_detail.php?id=<?= $p['id'] ?>" class="btn btn-sm btn-outline-primary">Detail</a><a href="add_allottee.php?property_id=<?= $p['id'] ?>" class="btn btn-sm btn-primary ms-1">Allot</a></td></tr><?php endforeach; ?><?php if (!$properties): ?><tr><td colspan="7" class="text-center text-muted">No vacant property found.</td></tr><?php endif; ?></tbody></table></div></main></div></body></html>
